134	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
135	    @Override
136	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
137	        List<String> missingFields = new ArrayList<>();
138	        if (isBlank(ownerFieldsDto.getFirstName())) {
139	            missingFields.add("firstName");
140	        }
141	        if (isBlank(ownerFieldsDto.getLastName())) {
142	            missingFields.add("lastName");
143	        }
144	        // Normalize whichever address form was supplied and fold it into the DTO: the structured
145	        // 'addressLine1'/'addressLine2' win when a non-blank 'addressLine1' is present, otherwise the
146	        // flat 'address' is used. The composed value is stored back into 'address' so every reader of
147	        // the owner's address sees the effective (structured-or-flat) value.
148	        applyAddress(ownerFieldsDto);
149	        if (isBlank(ownerFieldsDto.getAddress())) {
150	            missingFields.add("address");
151	        }
152	        if (isBlank(ownerFieldsDto.getCity())) {
153	            missingFields.add("city");
154	        }
155	        if (isBlank(ownerFieldsDto.getTelephone())) {
156	            missingFields.add("telephone");
157	        }
158	        if (!missingFields.isEmpty()) {
159	            throw new MissingOwnerFieldsException(missingFields);
160	        }
161	        validatePostcode(ownerFieldsDto.getCity(), ownerFieldsDto.getPostcode());
162	        LocalDate suppliedRegistrationDate = ownerFieldsDto.getRegistrationDate();
163	        if (suppliedRegistrationDate != null && suppliedRegistrationDate.isAfter(LocalDate.now())) {
164	            throw new FutureRegistrationDateException(
165	                "registrationDate must not be later than the server date");
166	        }
167	        LocalDate registrationDate = toBusinessDay(
168	            suppliedRegistrationDate != null
169	                ? suppliedRegistrationDate
170	                : LocalDate.now());
171	        long registeredOnDay = this.clinicService.findAllOwners().stream()
172	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
173	            .count();
174	        if (registeredOnDay >= 100) {
175	            throw new DailyRegistrationLimitException(
176	                "100 or more owners have already been registered today");
177	        }
178	        boolean bulkSignupWarning = registeredOnDay > 80;
179	        String city = ownerFieldsDto.getCity();
180	        long ownersInCity = this.clinicService.findAllOwners().stream()
181	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
182	            .count();
183	        if (ownersInCity >= 50) {
184	            throw new CityAtCapacityException(
185	                "the owner's city already contains 50 or more owners");
186	        }
187	        String telephone = toE164(ownerFieldsDto.getTelephone());
188	        ownerFieldsDto.setTelephone(telephone);
189	        String email = normalizeEmail(ownerFieldsDto.getEmail());
190	        ownerFieldsDto.setEmail(email);
191	        String lastName = normalizeHousehold(ownerFieldsDto.getLastName());
192	        String postcode = ownerFieldsDto.getPostcode();
193	        // Deterministic household id: owners with the same normalized last name and postcode
194	        // share it automatically, regardless of creation order. It is no longer created by the
195	        // 'sharesHousehold' flag; that flag now only bypasses the duplicate block below.
196	        String householdId = householdId(lastName, postcode);
197	        // The household is keyed on (last name, postcode), so its existing members are the
198	        // existing owners with the same computed household id. Both the duplicate block and the
199	        // household size below key off this value.
200	        List<Owner> householdMembers = this.clinicService.findAllOwners().stream()
201	            .filter(existing -> householdId.equals(
202	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode())))
203	            .toList();
204	        // Household duplicate block: a second owner in an existing household is rejected as a
205	        // household duplicate (409) unless the request opts in via 'sharesHousehold'. Opting in
206	        // only bypasses this block; the owner is then created as a declared household member.
207	        if (!householdMembers.isEmpty()
208	            && !Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold())) {
209	            throw new DuplicateHouseholdException(
210	                "an owner with the same last name and postcode already exists");
211	        }
212	        // Single, consolidated duplicate check: reject only when the new owner's whole
213	        // derived identity key (telephone|email|householdId) equals an existing owner's.
214	        String identityKey = IdentityKeyDeriver.identityKey(telephone, email, householdId);
215	        boolean identityInUse = this.clinicService.findAllOwners().stream()
216	            .anyMatch(existing -> identityKey.equals(IdentityKeyDeriver.identityKey(
217	                existing.getTelephone(), existing.getEmail(),
218	                householdId(normalizeHousehold(existing.getLastName()), existing.getPostcode()))));
219	        if (identityInUse) {
220	            throw new DuplicateIdentityException(
221	                "an owner with the same identity key already exists");
222	        }
223	        HttpHeaders headers = new HttpHeaders();
224	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
225	        owner.setRegistrationDate(registrationDate);
226	        owner.setCustomerCode(deduplicateCustomerCode(
227	            customerCode(owner.getPostcode(), owner.getTelephone(), owner.getLastName())));
228	        owner.setHouseholdId(householdId);
229	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
230	        owner.setBulkSignupWarning(bulkSignupWarning);
231	        // Household size after this create: existing members plus the owner being created.
232	        owner.setHouseholdSize(householdMembers.size() + 1);
233	        // A declared household member is not a suspected duplicate, and no other create path
234	        // reaches here for a same-household owner, so a created owner is never flagged.
235	        owner.setPossibleDuplicate(false);
236	        owner.setPossibleDuplicateOf(null);
237	        this.clinicService.saveOwner(owner);
238	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
239	        AUDIT.info("owner created: id={} customerCode={} registrationDate={} membershipLevel={} "
240	            + "membershipNumber={}",
241	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
242	            ownerDto.getMembershipLevel(), ownerDto.getMembershipNumber());
243	        headers.setLocation(UriComponentsBuilder.newInstance()
244	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
245	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
246	    }
