345	    private static boolean isBlank(String value) {
346	        return value == null || value.isBlank();
347	    }
348	
349	    /**
350	     * Rolls a registration date forward to the next business day: when it falls on a Saturday or
351	     * Sunday it is advanced to the following Monday; a weekday is returned unchanged. This is applied
352	     * to the effective registration date (whether supplied in the request or defaulted to the server
353	     * date), so every value derived from the registration date sees the adjusted business day.
354	     */
355	    private static LocalDate toBusinessDay(LocalDate date) {
356	        while (date.getDayOfWeek() == DayOfWeek.SATURDAY || date.getDayOfWeek() == DayOfWeek.SUNDAY) {
357	            date = date.plusDays(1);
358	        }
359	        return date;
360	    }
361	
362	    /**
363	     * Normalizes a last name for household-duplicate comparison: leading and trailing whitespace is
364	     * trimmed, every internal run of whitespace is collapsed to a single space, and the result is
365	     * lower-cased so that last names are compared case-insensitively.
366	     */
367	    private static String normalizeHousehold(String value) {
368	        return value == null ? "" : value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
369	    }
370	
371	    /** Common street-type abbreviations expanded to their canonical full form during normalization. */
372	    private static final Map<String, String> ADDRESS_ABBREVIATIONS =
373	        Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
374	
375	    /**
376	     * Normalizes an address to its canonical stored form: leading and trailing whitespace is
377	     * trimmed, every internal run of whitespace is collapsed to a single space, the result is
378	     * upper-cased, and common street-type abbreviations are expanded token-by-token
379	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} or
380	     * whitespace-only value normalizes to the empty string. This form is both stored/returned and
381	     * used for every address comparison (household-duplicate detection and the shared household id).
382	     */
383	    private static String normalizeAddress(String value) {
384	        if (value == null) {
385	            return "";
386	        }
387	        String collapsed = value.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
388	        if (collapsed.isEmpty()) {
389	            return "";
390	        }
391	        String[] tokens = collapsed.split(" ");
392	        StringBuilder sb = new StringBuilder();
393	        for (int i = 0; i < tokens.length; i++) {
394	            if (i > 0) {
395	                sb.append(' ');
396	            }
397	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
398	        }
399	        return sb.toString();
400	    }
401	
402	    /**
403	     * Folds an owner's supplied address into its canonical stored form on the given DTO, preferring
404	     * the structured fields when present. When a non-blank {@code addressLine1} is supplied, it and an
405	     * optional {@code addressLine2} are normalized ({@link #normalizeAddress}) and kept as the
406	     * structured lines; the flat {@code address} is set to the composed value ({@code addressLine1},
407	     * plus a single space and {@code addressLine2} when the second line is present). Otherwise the
408	     * structured lines are cleared and the flat {@code address} is set to the normalized flat input.
409	     * The resulting {@code address} is the effective value every address reader sees, and is blank
410	     * only when neither an {@code addressLine1} nor a flat {@code address} was supplied.
411	     */
412	    private static void applyAddress(OwnerFieldsDto ownerFieldsDto) {
413	        String line1 = normalizeAddress(ownerFieldsDto.getAddressLine1());
414	        String line2 = normalizeAddress(ownerFieldsDto.getAddressLine2());
415	        if (!isBlank(line1)) {
416	            ownerFieldsDto.setAddressLine1(line1);
417	            ownerFieldsDto.setAddressLine2(isBlank(line2) ? null : line2);
418	            ownerFieldsDto.setAddress(isBlank(line2) ? line1 : line1 + " " + line2);
419	        } else {
420	            ownerFieldsDto.setAddressLine1(null);
421	            ownerFieldsDto.setAddressLine2(null);
422	            ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
423	        }
424	    }
425	
426	    /**
427	     * Derives the stable {@code householdId} shared by all owners in a household: the first 12
428	     * hex characters of SHA-256 over {@code normalizedLastName + '|' + postcode}. It is a pure,
429	     * deterministic function of the normalized last name and postcode, so every owner that shares
430	     * those values maps to the same identifier regardless of creation order. A {@code null}
431	     * postcode contributes the empty string.
432	     */
433	    private static String householdId(String normalizedLastName, String postcode) {
434	        String key = normalizedLastName + "|" + (postcode == null ? "" : postcode);
435	        return sha256Hex12(key);
436	    }
437	
438	    /** The first 12 lower-case hex characters (6 bytes) of the SHA-256 digest of {@code s}. */
439	    private static String sha256Hex12(String s) {
440	        try {
441	            byte[] digest = MessageDigest.getInstance("SHA-256")
442	                .digest(s.getBytes(StandardCharsets.UTF_8));
443	            StringBuilder sb = new StringBuilder(12);
444	            for (int i = 0; i < 6; i++) {
445	                sb.append(String.format("%02x", digest[i]));
446	            }
447	            return sb.toString();
448	        }
449	        catch (NoSuchAlgorithmException e) {
450	            throw new IllegalStateException("SHA-256 not available", e);
451	        }
452	    }
453	
454	    /**
455	     * Builds the {@code customerCode} assigned to a new owner, formatted
456	     * {@code '<REGION>-<HASH8>'}: {@code REGION} is the region code derived from the owner's postcode
457	     * ({@code NSW}/{@code VIC}/{@code QLD}, or {@code UNKNOWN}), and {@code HASH8} is the first 8
458	     * upper-case hex characters of SHA-256 over the owner's normalized E.164 telephone concatenated
459	     * with the last name (e.g. {@code 'NSW-1A2B3C4D'}). No sequence number is used, so the code is a
460	     * pure function of the owner's own identity fields.
461	     */
462	    private static String customerCode(String postcode, String telephone, String lastName) {
463	        String region = LocalityDeriver.region(postcode);
464	        String hash8 = sha256Hex8((telephone == null ? "" : telephone)
465	            + (lastName == null ? "" : lastName));
466	        return region + "-" + hash8;
467	    }
468	
469	    /**
470	     * De-duplicates a computed {@code customerCode} against the codes already assigned to existing
471	     * owners. If {@code base} is not currently in use it is returned unchanged; otherwise
472	     * {@code '-<n>'} is appended with the smallest {@code n} of 2 or more that yields a code no
473	     * existing owner holds (e.g. a second collision on {@code 'NSW-1A2B3C4D'} becomes
474	     * {@code 'NSW-1A2B3C4D-2'}, a third {@code 'NSW-1A2B3C4D-3'}, and so on).
475	     */
476	    private String deduplicateCustomerCode(String base) {
477	        Set<String> existing = this.clinicService.findAllOwners().stream()
478	            .map(Owner::getCustomerCode)
479	            .filter(code -> code != null)
480	            .collect(Collectors.toSet());
481	        if (!existing.contains(base)) {
482	            return base;
483	        }
484	        int n = 2;
485	        while (existing.contains(base + "-" + n)) {
486	            n++;
487	        }
488	        return base + "-" + n;
489	    }
490	
491	    /** The first 8 upper-case hex characters (4 bytes) of the SHA-256 digest of {@code s}. */
492	    private static String sha256Hex8(String s) {
493	        try {
494	            byte[] digest = MessageDigest.getInstance("SHA-256")
495	                .digest(s.getBytes(StandardCharsets.UTF_8));
496	            StringBuilder sb = new StringBuilder(8);
497	            for (int i = 0; i < 4; i++) {
498	                sb.append(String.format("%02X", digest[i]));
499	            }
500	            return sb.toString();
501	        }
502	        catch (NoSuchAlgorithmException e) {
503	            throw new IllegalStateException("SHA-256 not available", e);
504	        }
505	    }
506	
507	    /**
508	     * Counts the existing owners that share the given first name and last name, compared
509	     * case-insensitively. This is evaluated over the owners that already exist (i.e. before the
510	     * owner currently being created is saved), so it reflects how many namesakes preceded the
511	     * new owner.
512	     */
513	    private int countNamesakes(String firstName, String lastName) {
514	        return (int) this.clinicService.findAllOwners().stream()
515	            .filter(existing -> firstName != null && firstName.equalsIgnoreCase(existing.getFirstName())
516	                && lastName != null && lastName.equalsIgnoreCase(existing.getLastName()))
517	            .count();
518	    }
519	
520	    /**
521	     * Normalizes a telephone number to E.164 form. Spaces, dashes and brackets are stripped. A
522	     * leading {@code '+'} and its country code are kept as-is; otherwise the number is treated as a
523	     * national one, a single leading {@code '0'} is dropped, and the default country code
524	     * {@code '+61'} is prepended. The result must have 8 to 15 digits after the {@code '+'}, and its
525	     * national number must have the length required by its country code ({@code '+61'} requires 9
526	     * national digits, {@code '+1'} requires 10); otherwise an {@link InvalidTelephoneException} is
527	     * raised (reported to the client as 400).
528	     */
529	    private static String toE164(String telephone) {
530	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s()-]", "");
531	        String digits;
532	        if (cleaned.startsWith("+")) {
533	            digits = cleaned.substring(1);
534	        } else {
535	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
536	            digits = "61" + national;
537	        }
538	        if (!digits.matches("[0-9]{8,15}")) {
539	            throw new InvalidTelephoneException(
540	                "telephone must form a valid E.164 number with 8 to 15 digits");
541	        }
542	        validateNationalLength(digits);
543	        return "+" + digits;
544	    }
545	
546	    /** National-number length required for each supported country code (digits after the code). */
547	    private static final Map<String, Integer> NATIONAL_LENGTH_BY_COUNTRY_CODE = Map.of(
548	        "61", 9, "1", 10);
549	
550	    /**
551	     * Validates the national-number length of an E.164 number (digits after the {@code '+'}) against
552	     * its country code. {@code '+61'} requires 9 national digits and {@code '+1'} requires 10; a
553	     * mismatch raises an {@link InvalidTelephoneException} (reported to the client as 400). Country
554	     * codes without a configured requirement are left to the general 8-to-15-digit rule.
555	     */
556	    private static void validateNationalLength(String digits) {
557	        for (Map.Entry<String, Integer> entry : NATIONAL_LENGTH_BY_COUNTRY_CODE.entrySet()) {
558	            String code = entry.getKey();
559	            if (digits.startsWith(code)) {
560	                int nationalLength = digits.length() - code.length();
561	                if (nationalLength != entry.getValue()) {
562	                    throw new InvalidTelephoneException(
563	                        "telephone national number must have " + entry.getValue()
564	                            + " digits for country code +" + code);
565	                }
566	                return;
567	            }
568	        }
569	    }
570	
571	    /**
572	     * Inclusive 4-digit postcode range fixed for each region: NSW 2000-2099, VIC 3000-3099,
573	     * QLD 4000-4099. A region absent from this table (i.e. a city with no known region) accepts
574	     * any 4-digit postcode.
575	     */
576	    private static final Map<String, int[]> REGION_POSTCODE_RANGE = Map.of(
577	        "NSW", new int[] {2000, 2099},
578	        "VIC", new int[] {3000, 3099},
579	        "QLD", new int[] {4000, 4099});
580	
581	    /**
582	     * Validates an owner's optional {@code postcode}. When absent (or blank) it is left unvalidated
583	     * and the owner is accepted, keeping the request contract backward-compatible. When present it
584	     * must be a 4-digit value; and when the owner's city maps to a known region it must fall within
585	     * that region's fixed inclusive range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099). A city with
586	     * no known region accepts any 4-digit postcode. A violation raises an
587	     * {@link InvalidPostcodeException} (reported to the client as 400).
588	     */
589	    private static void validatePostcode(String city, String postcode) {
590	        if (isBlank(postcode)) {
591	            return;
592	        }
593	        if (!postcode.matches("[0-9]{4}")) {
594	            throw new InvalidPostcodeException("postcode must be a 4-digit value");
595	        }
596	        int[] range = REGION_POSTCODE_RANGE.get(LocalityDeriver.localityForCity(city));
597	        if (range == null) {
598	            return;
599	        }
600	        int value = Integer.parseInt(postcode);
601	        if (value < range[0] || value > range[1]) {
602	            throw new InvalidPostcodeException(
603	                "postcode is out of range for the owner's city region");
604	        }
605	    }
606	
607	    /**
608	     * Disposable email domains that are rejected outright: an owner whose email domain is one of
609	     * these is refused with a 400. Compared case-insensitively (the email is lower-cased before the
610	     * check).
611	     */
612	    private static final Set<String> DISPOSABLE_EMAIL_DOMAINS = Set.of(
613	        "mailinator.com", "tempmail.com", "guerrillamail.com");
614	
615	    /**
616	     * Email is optional: an absent (or blank) value is left as {@code null}. When a value is
617	     * present it must be a syntactically valid address, otherwise an {@link InvalidEmailException}
618	     * is raised (reported to the client as 400). Its domain must not be on the disposable-domain
619	     * blocklist ({@code mailinator.com}, {@code tempmail.com}, {@code guerrillamail.com}), otherwise
620	     * an {@link InvalidEmailException} is likewise raised (400). A valid value is returned lower-cased
621	     * so it is stored and returned in canonical form.
622	     */
623	    private static String normalizeEmail(String email) {
624	        if (isBlank(email)) {
625	            return null;
626	        }
627	        String trimmed = email.trim();
628	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
629	            throw new InvalidEmailException("email must be a syntactically valid address");
630	        }
631	        String normalized = trimmed.toLowerCase(Locale.ROOT);
632	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
633	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
634	            throw new InvalidEmailException("email domain is on the disposable-domain blocklist");
635	        }
636	        return normalized;
637	    }
638	}
